import{_ as o,o as a,c as d,a5 as c}from"./chunks/framework.DJo0M80U.js";const l=JSON.parse('{"title":"java有哪些版本","description":"","frontmatter":{"title":"java有哪些版本","date":"2026-07-03T00:00:00.000Z","categories":["Java 快速入门"],"tags":["Java","Java基础","OneNote"],"lastUpdated":false},"headers":[],"relativePath":"posts/java快速入门/第一部分：语言基础/00-开发环境/java有哪些版本.md","filePath":"posts/java快速入门/第一部分：语言基础/00-开发环境/java有哪些版本.md"}'),t={name:"posts/java快速入门/第一部分：语言基础/00-开发环境/java有哪些版本.md"};function v(p,e,s,_,J,r){return a(),d("div",null,[...e[0]||(e[0]=[c("<div><p><code>java</code></p><p>分三个版本：<code>JavaSE(</code>标准版<code>)</code>、<code>JavaEE(</code>企业版<code>)</code>、<code>JavaME(</code>微型版<code>)</code> 其中<code>SE</code>就是大家学的<code>Java</code>基础，<code>EE</code>是公司最常用的用于网站开发<code>(PC</code>端<code>)</code>，<code>ME</code>用于移动端开发，现在熟悉的安卓系统就是用<code>JAVAME</code>开发的。</p><p><code>Java</code>既可以被编译，也可以被解释。通过编译器，可以把<code>Java</code>程序翻译成一种中间代码<code>-</code>称为字节码<code>-</code>可以被<code>Java</code>解释器解释的独立于平台的代码。通过解释器，每条<code>Java</code>字节指令被分析，然后在计算机上运行。只需编译一次，程序运行时解释执行。</p><p><code>Java</code>不同于一般的编译执行计算机语言和解释执行计算机语言。它首先将源代码编译成二进制字节码<code>(bytecode)</code>，然后依赖各种不同平台上的虚拟机来解释执行字节码，从而实现了“一次编译、到处执行”的跨平台特性 或者用一种更总结性的话术来表达就是：<code>java</code>跨平台就是能在不同的环境<code>(</code>主要是操作系统<code>)</code>上运行<code>java</code>程序！</p><p>这也是<code>Java</code>为什么这么火，为什么这么多年依然屹立不倒且久盛而不衰的原因。一个无视于平台，跨平台的语言，必然有长久的生命力。而作为程序员来说，职业发展的长远规划，选择<code>Java</code>远比选择其他无法实现跨平台的语言，更有长远价值！ 相似的<code>JAVAEE</code>、<code>javase</code>、<code>javame</code>可简单的总结为三点：</p><p><code>JavaSE</code>是做电脑上运行的软件。 <code>JavaEE</code>是用来做网站的<code>-(</code>我们常见的<code>JSP</code>技术</p><ul><li>)</li><li>JavaME</li></ul><p>是做手机软件的。 想更细致了解<code>java</code>，可以百度搜索圈<code>T</code>社区，相应<code>java</code>板块有详细视频教程。纯干货！</p></div>",1)])])}const n=o(t,[["render",v]]);export{l as __pageData,n as default};
